import{_ as t}from"./chunks/3510_sync_control_mode_diagram.0Bz4--2d.js";import{_ as a,o as _,a as e,b as s}from"./app.DKoEZOcr.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"同步控制","link":"/api/SIMD-API/c_api/sync/sync"},{"text":"系统同步能力概述","link":"/api/SIMD-API/c_api/sync/system_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/sync/system_sync_overview.md","filePath":"api/SIMD-API/c_api/sync/system_sync_overview.md","lastUpdated":1787832553000}'),r={name:"api/SIMD-API/c_api/sync/system_sync_overview.md"};function o(d,c,i,n,l,y){return _(),e("div",null,[...c[0]||(c[0]=[s('<div><article class="markdown-body"><h1>系统同步能力概述</h1><p>在编程中，同步是指协调多个执行单元（如线程、进程等）对共享资源的访问顺序和时机来确保程序的正确性。如果没有同步来严格控制执行顺序，则会出现结果不一致、行为不可预测等多种问题。</p><p>AI Core的同步，总共分成2类：<a href="intra_core_sync_overview.html">核内同步</a>、<a href="inter_core_sync_overview.html">核间同步</a>。各类同步对应的接口如下。</p><p><strong>表1</strong> 核内同步接口</p><table><thead><tr><th>接口名称</th><th>功能简述</th></tr></thead><tbody><tr><td><a href="asc_sync_notify.html">asc_sync_notify</a>/<a href="asc_sync_wait.html">asc_sync_wait</a></td><td>多流水同步：同一核内不同流水之间的同步指令。<code>asc_sync_notify</code>负责发送通知，<code>asc_sync_wait</code>负责阻塞直到<code>asc_sync_notify</code>发送通知。</td></tr><tr><td><a href="asc_sync_pipe.html">asc_sync_pipe</a></td><td>单流水同步：同一核内相同流水之间的同步指令（不支持<code>PIPE_S</code>单流水同步）。</td></tr><tr><td><a href="asc_sync_data_barrier.html">asc_sync_data_barrier</a></td><td>阻塞后续的指令执行，直到所有之前的内存访问指令（需要等待的内存位置可通过参数控制）执行结束。</td></tr><tr><td><a href="asc_lock.html">asc_lock</a>/<a href="asc_unlock.html">asc_unlock</a></td><td>用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖。</td></tr></tbody></table><p>如图1所示，支持的四种同步控制模式的功能描述如下：</p><ul><li>模式0：AI Core核间的同步控制。对于AIC全核场景，同步所有的AIC核，直到所有的AIC核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行；对于AIV全核场景，同步所有的AIV核，直到所有的AIV核都执行到<code>asc_sync_inter_arrive</code>时，<code>asc_sync_inter_wait</code>后续的指令才会执行。</li><li>模式1：AI Core内部，AIV核之间的同步控制。如果两个AIV核都运行了<code>asc_sync_subblock_arrive</code>，<code>asc_sync_subblock_wait</code>后续的指令才会执行。</li><li>模式2：AI Core内部，AIC与AIV之间的同步控制。在AIC核执行<code>asc_sync_block_arrive</code>之后，两个AIV上<code>asc_sync_block_wait</code>后续的指令才会继续执行；两个AIV都执行<code>asc_sync_block_arrive</code>后，AIC上<code>asc_sync_block_wait</code>后续的指令才能执行。</li><li>模式4：AI Core内部，AIC与单个AIV之间的同步控制。在单个AIV核执行<code>asc_sync_intra_arrive</code>之后，AIC上<code>asc_sync_intra_wait</code>后续的指令才会继续执行；AIC执行<code>asc_sync_intra_arrive</code>后，单个AIV上<code>asc_sync_intra_wait</code>后续的指令才能执行。AIV0与AIV1可单独触发AIC等待。</li></ul><p><strong>图1</strong> 同步控制模式示意图<span id="fig_sync_control_mode"></span><br><img src="'+t+'" alt></p><p><strong>表2</strong> 核间同步接口</p><table><thead><tr><th>接口名称</th><th>同步范围</th><th>对应模式</th><th>功能简述</th></tr></thead><tbody><tr><td><a href="asc_sync_inter_arrive.html">asc_sync_inter_arrive</a>/<a href="asc_sync_inter_wait.html">asc_sync_inter_wait</a></td><td>组间同步，即不同group之间所有block（所有AIC或所有AIV）之间的同步。</td><td>模式0（同步等待全部AIC或全部AIV执行结束）</td><td><code>asc_sync_inter_arrive</code>为生产者，负责发送通知；<code>asc_sync_inter_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_subblock_arrive.html">asc_sync_subblock_arrive</a>/<a href="asc_sync_subblock_wait.html">asc_sync_subblock_wait</a></td><td>组内subblock间的同步，即同一group内不同subblock（AIV）之间的同步。</td><td>模式1（单个AI Core内，全部AIV之间的同步）</td><td><code>asc_sync_subblock_arrive</code>为生产者，负责发送通知；<code>asc_sync_subblock_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_block_arrive.html">asc_sync_block_arrive</a>/<a href="asc_sync_block_wait.html">asc_sync_block_wait</a></td><td>同一group内block（AIC）与所有subblock（AIV）之间的同步。</td><td>模式2（单个AI Core内，AIC与全部AIV之间的同步）</td><td><code>asc_sync_block_arrive</code>为生产者，负责发送通知；<code>asc_sync_block_wait</code>为消费者，负责阻塞等待通知到达。</td></tr><tr><td><a href="asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>/<a href="asc_sync_intra_wait.html">asc_sync_intra_wait</a></td><td>同一group内block（AIC）与单个subblock（AIV）之间的同步。</td><td>模式4（单个AI Core内，AIC核与单个AIV之间同步）</td><td><code>asc_sync_intra_arrive</code>为生产者，负责发送通知；<code>asc_sync_intra_wait</code>为消费者，负责阻塞等待通知到达。</td></tr></tbody></table></article></div>',1)])])}const h=a(r,[["render",o]]);export{b as __pageData,h as default};
